export default function next({ body, previous }) {
  const input = JSON.parse(body.event),
    items = Array.isArray(input.data) ? input.data : [input],
    email = input.email ?? input.Email,
    index = previous?.index ?? 0,
    item = items[index];
  if (!item)
    return {
      more: false,
      state: { index },
      indicator: "https://example.test",
      email: email ?? "",
      isIp: false,
      rawIp: false,
      scanUrl: "https://example.test",
      ipRescanUrl: "https://www.virustotal.com/api/v3/ip_addresses/0.0.0.0/analyse",
      ip: "",
      dns: "https://dns.google/resolve",
    };
  const indicator = String(item.url ?? item.ip ?? "");
  if (!indicator || !email) throw Error("Provide an indicator and report email");
  const host = indicator.includes("://") ? new URL(indicator).hostname : indicator.split("/")[0],
    isIp = /^(?:\d{1,3}\.){3}\d{1,3}$/.test(host),
    dns = new URL("https://dns.google/resolve");
  dns.searchParams.set("name", host);
  dns.searchParams.set("type", "A");
  const rawIp = isIp && indicator === host,
    scanUrl = indicator.includes("://") ? indicator : "https://" + indicator;
  const ipRescanUrl =
    "https://www.virustotal.com/api/v3/ip_addresses/" + encodeURIComponent(host) + "/analyse";
  return {
    rawIp,
    scanUrl,
    ipRescanUrl,
    more: true,
    state: { index: index + 1 },
    indicator,
    email,
    isIp,
    ip: isIp ? host : "",
    dns: dns.toString(),
  };
}

