export default function ip({ direct, dns }) {
  if (direct) return { ip: direct };
  const answer = dns?.Answer?.filter((x) => x.type === 1).at(-1)?.data;
  if (!answer) throw Error("No IPv4 DNS answer");
  return { ip: answer };
}

