export default function urls({ ip, analysis, ipAnalysis }) {
  return {
    riot: "https://api.greynoise.io/v2/riot/" + encodeURIComponent(ip),
    context: "https://api.greynoise.io/v2/noise/context/" + encodeURIComponent(ip),
    analysis:
      "https://www.virustotal.com/api/v3/analyses/" +
      encodeURIComponent(analysis?.id ?? ipAnalysis?.data?.id ?? ""),
  };
}

