export default function status({ response }) {
  const data = response?.data,
    attrs = data?.attributes;
  if (!attrs?.status) throw Error("VirusTotal response has no status");
  if (!["queued", "in-progress", "completed"].includes(attrs.status))
    throw Error("Unexpected VirusTotal analysis status");
  return { completed: attrs.status === "completed", analysis: data };
}

