export default function report({ indicator, ip, email, analysis, riot, context }) {
  const a = analysis.attributes,
    s = a.stats,
    r = a.results;
  if (!s || !r) throw Error("VirusTotal result missing");
  const block = r.BlockList?.result ?? "n/a",
    phish = r.OpenPhish?.result ?? "n/a",
    location = context.metadata?.region
      ? `${context.metadata.region} ${context.metadata.country ?? ""}`
      : "n/a",
    tags = (context.tags ?? []).join(", ") || "None",
    trust = riot.trust_level ?? context.trust_level ?? "Not trusted",
    classification = context.classification ?? "safe",
    category = context.category ?? "n/a",
    total = (s.harmless ?? 0) + (s.malicious ?? 0) + (s.suspicious ?? 0) + (s.undetected ?? 0),
    text = `Successfully scanned ${indicator}${ip !== indicator ? " (" + ip + ")" : ""}\n\nVirusTotal Report (${total} scans)\n${s.harmless ?? 0} Harmless\n${s.malicious ?? 0} Malicious\n${s.suspicious ?? 0} Suspicious\n${s.undetected ?? 0} Undetected\n${s.timeout ?? 0} Timed out\nBlockList: ${block}\nOpenPhish: ${phish}\nSummary: ${(s.suspicious ?? 0) + (s.malicious ?? 0) === 0 ? "✅ Harmless" : "🚨 Malicious"}\n\nGreyNoise Report\nTrust Level: ${trust}\nClassification: ${classification}\nLocation: ${location}\nCategory: ${category}\nTags: ${tags}`;
  return { text, email, subject: indicator + " Scan Report" };
}
